        // Fund depositor
        uint256 totalSend = baseline + amount;
        vm.deal(depositor, totalSend);

        // First deposit baseline
        vm.prank(depositor);
        c.deposit{value: baseline}();

        // Second deposit fuzzed amount
        vm.prank(depositor);
        c.deposit{value: amount}();

